/**
 * Batch Page Updater
 * 
 * Uses Claude + Gravito to systematically update all pages with:
 * - Light backgrounds
 * - Subtle industrial styling (analog, not heavy-handed)
 * - Brand-consistent content
 * 
 * This should be the FINAL website update because Gravito is now configured correctly.
 */

// Governed: routed through invokeLLM governance pipeline
import { governedClaude } from '../governance/governed-anthropic';
import * as fs from 'fs';
import * as path from 'path';
import { createSiteAuditService, type PageAuditResult } from './site-audit-service';
import { generalLog } from '../_core/logger';
import { MODELS } from "../_core/models";

const anthropic = governedClaude;

// ============================================================================
// TYPES
// ============================================================================

export interface PageUpdateResult {
  pagePath: string;
  status: 'updated' | 'skipped' | 'failed';
  reason?: string;
  changes?: string[];
}

export interface BatchUpdateReport {
  totalPages: number;
  updated: number;
  skipped: number;
  failed: number;
  results: PageUpdateResult[];
  completedAt: Date;
}

// ============================================================================
// BRAND GUIDELINES FOR CLAUDE
// ============================================================================

const BRAND_GUIDELINES = `
## Gravito Brand Guidelines for Page Updates

### Philosophy
Industrial era electricity is an ANALOG for AI governance, not a literal design mandate.
The aesthetic should be SUBTLE and CONSUMABLE, not heavy-handed.

### Background
- Use LIGHT backgrounds (bg-white, bg-gray-50, bg-amber-50/10)
- Remove dark backgrounds (bg-zinc-900, bg-slate-900, bg-black)
- Keep the page feeling open, approachable, and professional

### Industrial Elements - USE SPARINGLY
- Gauges: Only on key pages (Home, Product) - not everywhere
- Control panels: Use as accent borders/frames only
- Brass/amber: Subtle highlights, not overwhelming
- Industrial typography: Where appropriate, not forced

### Color Palette
- Primary: Amber (#B45309) for accents
- Background: White/light gray
- Text: Dark gray/black for readability
- Accents: Subtle amber highlights

### Typography
- Headlines: Can use Oswald where it fits naturally
- Body: System fonts for readability
- Don't force industrial fonts where they don't fit

### Content Tone
- Use industrial metaphors as ANALOGIES to explain concepts
- Don't force metaphors where they don't fit
- Keep language clear and consumable
- Avoid: revolutionary, game-changing, cutting-edge, leverage, synergy

### What to Update
1. Change dark backgrounds to light
2. Remove excessive industrial decoration
3. Keep subtle amber accents
4. Ensure text is readable
5. Maintain professional, approachable feel
`;

// ============================================================================
// PAGE UPDATE LOGIC
// ============================================================================

async function generatePageUpdate(
  currentContent: string,
  pagePath: string,
  auditResult: PageAuditResult
): Promise<string | null> {
  const issues = auditResult.issues.join('\n- ');
  const recommendations = auditResult.recommendations.join('\n- ');

  const prompt = `You are updating a React/TypeScript page for the Gravito website.

${BRAND_GUIDELINES}

## Current Page Issues
- ${issues || 'No specific issues identified'}

## Recommendations
- ${recommendations || 'General brand alignment needed'}

## Current Page Content
\`\`\`tsx
${currentContent}
\`\`\`

## Your Task
Update this page to:
1. Use LIGHT backgrounds (change bg-zinc-900, bg-slate-900 to bg-white, bg-gray-50)
2. Keep industrial elements SUBTLE (don't add gauges everywhere)
3. Use amber accents sparingly
4. Ensure all text is readable
5. Maintain the page's functionality

Return ONLY the updated TypeScript/React code. No explanations.
If the page is already well-aligned, return it with minimal changes.`;

  const maxRetries = 3;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const response = await anthropic.messages.create({
        model: MODELS.generation,
        max_tokens: 8000,
        messages: [{ role: 'user', content: prompt }]
      });

      const text = response.content[0].type === 'text' ? response.content[0].text : '';

      // Extract code from markdown code blocks if present
      const codeMatch = text.match(/```(?:tsx?|typescript|javascript)?\n([\s\S]*?)```/);
      if (codeMatch) {
        return codeMatch[1].trim();
      }

      // If no code block, return the raw text (might be direct code)
      return text.trim();
    } catch (error: unknown) {
      generalLog.info(`[BatchUpdater] Attempt ${attempt}/${maxRetries} failed for ${pagePath}: ${error.message}`);
      if (attempt < maxRetries) {
        // Wait before retry with exponential backoff
        await new Promise(resolve => setTimeout(resolve, 2000 * attempt));
      } else {
        generalLog.error(`[BatchUpdater] All retries failed for ${pagePath}`);
        return null;
      }
    }
  }
  return null;
}

async function validateUpdate(
  updatedContent: string,
  pagePath: string
): Promise<{ valid: boolean; issues: string[] }> {
  // Basic validation checks
  const issues: string[] = [];

  // Check for dark backgrounds that should be removed
  const darkPatterns = ['bg-zinc-900', 'bg-slate-900', 'bg-gray-900', 'bg-black'];
  for (const pattern of darkPatterns) {
    if (updatedContent.includes(pattern)) {
      issues.push(`Still contains dark background: ${pattern}`);
    }
  }

  // Check for light backgrounds
  const lightPatterns = ['bg-white', 'bg-gray-50', 'bg-slate-50', 'bg-amber-50'];
  const hasLight = lightPatterns.some(p => updatedContent.includes(p));
  if (!hasLight) {
    issues.push('Missing light background classes');
  }

  // Check for basic React structure
  if (!updatedContent.includes('export') || !updatedContent.includes('return')) {
    issues.push('Missing React component structure');
  }

  return {
    valid: issues.length === 0,
    issues
  };
}

// ============================================================================
// BATCH UPDATE FUNCTIONS
// ============================================================================

export async function updateSinglePage(
  pagePath: string,
  auditResult: PageAuditResult,
  dryRun: boolean = false
): Promise<PageUpdateResult> {
  const filePath = auditResult.pageInfo.filePath;

  // Skip if already aligned
  if (auditResult.completionStatus === 'aligned') {
    return {
      pagePath,
      status: 'skipped',
      reason: 'Already aligned with brand'
    };
  }

  try {
    // Read current content
    const currentContent = await fs.promises.readFile(filePath, 'utf-8');

    // Generate update using Claude
    generalLog.info(`[BatchUpdater] Generating update for ${pagePath}...`);
    const updatedContent = await generatePageUpdate(currentContent, pagePath, auditResult);

    if (!updatedContent) {
      return {
        pagePath,
        status: 'failed',
        reason: 'Failed to generate update'
      };
    }

    // Validate the update
    const validation = await validateUpdate(updatedContent, pagePath);
    if (!validation.valid) {
      generalLog.info(`[BatchUpdater] Validation failed for ${pagePath}:`, validation.issues);
      // Still apply if it's an improvement
    }

    // Apply the update (unless dry run)
    if (!dryRun) {
      await fs.promises.writeFile(filePath, updatedContent, 'utf-8');
      generalLog.info(`[BatchUpdater] Updated ${pagePath}`);
    } else {
      generalLog.info(`[BatchUpdater] [DRY RUN] Would update ${pagePath}`);
    }

    return {
      pagePath,
      status: 'updated',
      changes: [
        'Converted to light background',
        'Applied subtle industrial styling',
        ...validation.issues.map(i => `Warning: ${i}`)
      ]
    };
  } catch (error: unknown) {
    return {
      pagePath,
      status: 'failed',
      reason: error.message
    };
  }
}

export async function updatePagesByPriority(
  priority: 'high' | 'medium' | 'low',
  dryRun: boolean = false
): Promise<BatchUpdateReport> {
  const auditService = createSiteAuditService();
  const report = await auditService.auditAllPages();

  const pagesToUpdate = report.prioritizedActions[priority];
  const results: PageUpdateResult[] = [];

  generalLog.info(`[BatchUpdater] Updating ${pagesToUpdate.length} ${priority}-priority pages...`);

  for (const page of pagesToUpdate) {
    const result = await updateSinglePage(page.pageInfo.routePath, page, dryRun);
    results.push(result);

    // Small delay to avoid rate limiting
    await new Promise(resolve => setTimeout(resolve, 1000));
  }

  return {
    totalPages: pagesToUpdate.length,
    updated: results.filter(r => r.status === 'updated').length,
    skipped: results.filter(r => r.status === 'skipped').length,
    failed: results.filter(r => r.status === 'failed').length,
    results,
    completedAt: new Date()
  };
}

export async function updateAllPages(
  dryRun: boolean = false
): Promise<BatchUpdateReport> {
  const auditService = createSiteAuditService();
  const report = await auditService.auditAllPages();

  const allPagesToUpdate = [
    ...report.prioritizedActions.high,
    ...report.prioritizedActions.medium,
    ...report.prioritizedActions.low
  ];

  const results: PageUpdateResult[] = [];

  generalLog.info(`[BatchUpdater] Updating ${allPagesToUpdate.length} pages total...`);

  for (let i = 0; i < allPagesToUpdate.length; i++) {
    const page = allPagesToUpdate[i];
    generalLog.info(`[BatchUpdater] Processing ${i + 1}/${allPagesToUpdate.length}: ${page.pageInfo.routePath}`);

    const result = await updateSinglePage(page.pageInfo.routePath, page, dryRun);
    results.push(result);

    // Small delay to avoid rate limiting
    await new Promise(resolve => setTimeout(resolve, 500));
  }

  return {
    totalPages: allPagesToUpdate.length,
    updated: results.filter(r => r.status === 'updated').length,
    skipped: results.filter(r => r.status === 'skipped').length,
    failed: results.filter(r => r.status === 'failed').length,
    results,
    completedAt: new Date()
  };
}

// ============================================================================
// EXPORTS
// ============================================================================

export { BRAND_GUIDELINES };

